"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Fraction } from "@/components/ui/fraction"

type StepsProps = Omit<React.ComponentProps<"ol">, "defaultValue"> & {
  /**
   * margin: large thin numerals in the margin.
   * rise: the numerals stand on one line across the page; those to come are sunk into it and rise out as you reach them.
   * cascade: no numerals; the titles step across the page like a broken headline, an arrow pointing on from where you are.
   * folio: the compact one. The sequence folds into one fraction, "02/05", beside the step you're on.
   */
  variant?: "margin" | "rise" | "cascade" | "folio"
  /**
   * The step you're on, counted from 1 as the numerals are; the steps before it are done. One past the last means
   * all done. Left out, each Step's own `current` and `done` say where you are.
   */
  value?: number
  defaultValue?: number
  /** Makes the steps behind you a way back: their titles become buttons that call this with the step's number. */
  onValueChange?: (value: number) => void
}

const Sequence = React.createContext<{ at?: number; go?: (n: number) => void; shown?: number }>({})
const Place = React.createContext(0) // this step's number, from 1
const Reached = React.createContext({ n: 0, done: false })

/** A real sequence, numbered. Only use it when the order matters. */
function Steps({ className, variant = "margin", value, defaultValue, onValueChange, children, ...props }: StepsProps) {
  const [own, setOwn] = React.useState(defaultValue)
  const kids = React.Children.toArray(children).filter(React.isValidElement<StepProps>)
  const at = value ?? own
  // The folio says where you are as one figure: the step you're on, or the last one reached.
  const here = Math.min(Math.max(at ?? (kids.findIndex((k) => k.props.current) + 1 || kids.filter((k) => k.props.done).length + 1), 1), kids.length)
  const shown = variant === "folio" ? here : undefined
  const go = onValueChange
    ? (n: number) => {
        if (value === undefined) setOwn(n)
        onValueChange(n)
      }
    : undefined
  const list = (
    <ol data-slot="steps" data-variant={variant} className={cn("ot-steps", className)} {...props}>
      <Sequence.Provider value={{ at, go, shown }}>
        {kids.map((kid, i) => (
          <Place.Provider key={kid.key ?? i} value={i + 1}>
            {kid}
          </Place.Provider>
        ))}
      </Sequence.Provider>
    </ol>
  )
  if (variant !== "folio") return list
  // The list stays whole for a screen reader; only the step shown beside the figure is seen.
  return (
    <div className="ot-steps-folio">
      <Fraction count={String(here).padStart(2, "0")} total={String(kids.length).padStart(2, "0")} aria-hidden="true" />
      {list}
    </div>
  )
}

type StepProps = React.ComponentProps<"li"> & {
  /** The step the person is on: its numeral is the view's one accent. Left out, Steps' `value` decides. */
  current?: boolean
  done?: boolean
}

function Step({ className, current, done, ...props }: StepProps) {
  const { at, shown } = React.useContext(Sequence)
  const n = React.useContext(Place)
  const here = current ?? (at !== undefined && n === at)
  const behind = done ?? (at !== undefined && n < at)
  return (
    <Reached.Provider value={{ n, done: behind }}>
      <li
        data-slot="step"
        data-current={here || undefined}
        data-done={behind || undefined}
        data-shown={n === shown || undefined}
        aria-current={here ? "step" : undefined}
        className={cn("ot-step", className)}
        {...props}
      />
    </Reached.Provider>
  )
}

/** The step's name. Behind you, with `onValueChange` on Steps, it's a button back to that step. */
function StepTitle({ className, children, ...props }: React.ComponentProps<"h3">) {
  const { go, shown } = React.useContext(Sequence)
  const { n, done } = React.useContext(Reached)
  return (
    <h3 data-slot="step-title" className={cn("ot-step-title", className)} {...props}>
      {go && done && shown === undefined ? ( // ponytail: the folio hides the steps behind you, so it offers no way back; pair it with your own Back button
        <button type="button" className="ot-step-back" onClick={() => go(n)}>
          {children}
          <span className="ot-sr">, done. Go back to this step.</span>
        </button>
      ) : (
        children
      )}
    </h3>
  )
}

export { Steps, Step, StepTitle, type StepsProps, type StepProps }

@layer components {
  /* ── ot-steps ── a real sequence: large thin numerals in pencil, two figures as the posters number
     ("Less is more." 01), a hairline between steps; the current numeral is the one accent and lands with a
     small rebound when the sequence moves on. */
  .ot-steps { list-style: none; margin: 0; padding: 0; counter-reset: ot-step; display: grid; gap: var(--ot-space-6); }
  .ot-step {
    counter-increment: ot-step;
    display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: var(--ot-space-5);
    padding-block-start: var(--ot-space-4); border-block-start: var(--ot-hairline) solid var(--ot-rule);
  }
  .ot-step::before {
    content: counter(ot-step, decimal-leading-zero); grid-row: 1 / span 3; align-self: start;
    font-size: var(--ot-f); line-height: 0.9; font-weight: 200; font-stretch: 88%; letter-spacing: -0.02em;
    font-variant-numeric: lining-nums tabular-nums; color: var(--ot-pencil);
  }
  .ot-step > * { grid-column: 2; min-inline-size: 0; }
  .ot-step > * + * { margin-block-start: var(--ot-space-3); } /* not row-gap: the numeral's spanned rows would each add one */
  .ot-step[data-done]::before { color: var(--ot-ink); }
  .ot-step[data-current]::before { color: var(--ot-accent); font-weight: 300; animation: ot-land var(--ot-moderato) var(--ot-spiccato); }
  .ot-step-title { margin: 0; font-size: var(--ot-mp); line-height: var(--ot-mp-lh); letter-spacing: var(--ot-mp-tr); font-weight: 400; color: var(--ot-ink); }

  /* rise: the numerals stand on one hairline across the page, huge and thin, like letters cut by a line in
     SPECTRA and Paul Rand's grid. A step to come is sunk into the line, only its top showing; reached, its
     numeral rises out whole (the accent), and it stays standing, in ink, once done. */
  .ot-steps[data-variant="rise"] { grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 0; }
  .ot-steps[data-variant="rise"] > .ot-step { grid-template-columns: minmax(0, 1fr); align-content: start; padding: 0; border: 0; }
  .ot-steps[data-variant="rise"] > .ot-step > * { grid-column: 1; padding-inline-end: var(--ot-space-5); }
  .ot-steps[data-variant="rise"] > .ot-step::before {
    grid-row: auto; box-sizing: border-box; block-size: calc(0.74em + var(--ot-hairline)); overflow: clip;
    padding-block-start: var(--ot-step-sink, 0.46em); margin-block-end: var(--ot-space-4);
    font-size: var(--ot-ff); line-height: 0.74; font-weight: 100; font-stretch: 100%; letter-spacing: -0.04em;
    border-block-end: var(--ot-hairline) solid var(--ot-rule-strong); animation: none;
    transition: padding-block-start var(--ot-andante) var(--ot-exhale), color var(--ot-moderato);
  }
  .ot-steps[data-variant="rise"] > .ot-step:is([data-done], [data-current]) { --ot-step-sink: 0em; }
  .ot-steps[data-variant="rise"] > .ot-step[data-current]::before { font-weight: 200; }
  @media (max-width: 40rem) {
    .ot-steps[data-variant="rise"] { grid-auto-flow: row; row-gap: var(--ot-space-6); }
    .ot-steps[data-variant="rise"] > .ot-step::before { font-size: var(--ot-f); }
  }

  /* cascade: no numerals. The titles are set as one broken headline that steps across the page, the way
     "Healthy habits → for creatives" breaks its line, so the order is read in the space itself. Behind you in
     pencil, ahead in graphite; where you are in ink, with the accent arrow pointing on to the next. The last
     step, reached, closes the headline with an accent full stop instead. */
  .ot-steps[data-variant="cascade"] { gap: var(--ot-space-5); }
  .ot-steps[data-variant="cascade"] > .ot-step { display: block; padding: 0; border: 0; margin-inline-start: calc(var(--ot-step-i, 0) * var(--ot-space-8)); }
  .ot-steps[data-variant="cascade"] > .ot-step:nth-child(2) { --ot-step-i: 1; }
  .ot-steps[data-variant="cascade"] > .ot-step:nth-child(3) { --ot-step-i: 2; }
  .ot-steps[data-variant="cascade"] > .ot-step:nth-child(4) { --ot-step-i: 3; }
  .ot-steps[data-variant="cascade"] > .ot-step:nth-child(n + 5) { --ot-step-i: 4; } /* ponytail: the stair stops at the fifth step so a long list keeps its measure */
  .ot-steps[data-variant="cascade"] > .ot-step::before { content: none; }
  .ot-steps[data-variant="cascade"] > .ot-step > * + * { margin-block-start: var(--ot-space-2); }
  .ot-steps[data-variant="cascade"] > .ot-step > :not(.ot-step-title) { color: var(--ot-pencil); }
  .ot-steps[data-variant="cascade"] .ot-step-title {
    font-size: var(--ot-mf); line-height: var(--ot-mf-lh); letter-spacing: var(--ot-mf-tr); font-weight: 300; color: var(--ot-graphite);
    transition: color var(--ot-moderato);
  }
  .ot-steps[data-variant="cascade"] > .ot-step[data-done] .ot-step-title { color: var(--ot-pencil); }
  .ot-steps[data-variant="cascade"] > .ot-step[data-current] .ot-step-title { color: var(--ot-ink); font-weight: 400; }
  .ot-steps[data-variant="cascade"] > .ot-step[data-current] > :not(.ot-step-title) { color: var(--ot-graphite); }
  .ot-steps[data-variant="cascade"] > .ot-step[data-current] .ot-step-title::after {
    content: "\2009\2192" / ""; display: inline-block; color: var(--ot-accent); font-weight: 300;
    animation: ot-step-onward var(--ot-moderato) var(--ot-spiccato) backwards;
  }
  .ot-steps[data-variant="cascade"] > .ot-step[data-current]:last-child .ot-step-title::after { content: "." / ""; }
  .ot-steps[data-variant="cascade"]:is([dir="rtl"], [dir="rtl"] *) > .ot-step[data-current]:not(:last-child) .ot-step-title::after { content: "\2009\2190" / ""; --ot-step-lr: -1; }
  @keyframes ot-step-onward { from { opacity: 0; translate: calc(-0.4em * var(--ot-step-lr, 1)) 0; } }
  @media (max-width: 40rem) {
    .ot-steps[data-variant="cascade"] > .ot-step { margin-inline-start: calc(var(--ot-step-i, 0) * var(--ot-space-5)); }
  }

  /* folio: the compact one. The whole sequence folds into one fraction, as SPECTRA prints 1/3 large beside its small
     notes and "Less is more." sets its 01: where you are in the accent italic, of how many small and upright after the
     pen stroke. The step you're on hangs beside it, its title on the figure's baseline. The other steps stay in the list,
     unseen, so a screen reader still hears the whole order. Moving on, the figure turns over (the fraction's roll). */
  .ot-steps-folio { display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: var(--ot-space-5); align-items: first baseline; }
  .ot-steps-folio > .ot-fraction { font-size: var(--ot-ff); }
  .ot-steps-folio > .ot-fraction > .ot-yours { color: var(--ot-accent); }
  .ot-steps-folio:not(:has([data-current])) > .ot-fraction > .ot-yours { color: var(--ot-ink); } /* all done: nowhere left to be */
  .ot-steps[data-variant="folio"] { display: block; }
  .ot-steps[data-variant="folio"] > .ot-step { display: block; padding: 0; border: 0; }
  .ot-steps[data-variant="folio"] > .ot-step::before { content: none; }
  .ot-steps[data-variant="folio"] > .ot-step > :not(.ot-step-title) { color: var(--ot-graphite); }
  .ot-steps[data-variant="folio"] > .ot-step:not([data-shown]) {
    position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap;
  }
  @media (max-width: 40rem) { .ot-steps-folio > .ot-fraction { font-size: var(--ot-f); } }

  /* A way back: with onValueChange, a done step's title is a button. Pointing draws a hairline under it. */
  .ot-step-back {
    appearance: none; margin: 0; padding: 0; border: 0; background: none; font: inherit; letter-spacing: inherit; color: inherit; text-align: inherit; cursor: pointer;
    text-decoration: underline var(--ot-hairline) transparent; text-underline-offset: 0.2em; transition: text-decoration-color var(--ot-allegro);
  }
  .ot-step-back:is(:hover, :focus-visible, [data-force~="hover"]) { text-decoration-color: currentColor; }

  @media (forced-colors: active) {
    .ot-step[data-current]::before, .ot-steps[data-variant="cascade"] > .ot-step[data-current] .ot-step-title::after, .ot-steps-folio > .ot-fraction > .ot-yours { color: Highlight; }
  }
}
